// @ts-nocheck
// Letterlijk overgenomen uit de goedgekeurde zelfstandige Getalbeelden-preview.
    const GETALBEELDEN_MATERIALS = [
      { id:'fingers', name:'Vingerbeeld', min:0, max:10, sample:5, source:'gegenereerde handbeelden 0–10' },
      { id:'dice', name:'Dobbelsteenbeeld', min:1, max:12, sample:5, source:'SupportMaterialPreview' },
      { id:'domino', name:'Dominobeeld', min:0, max:12, sample:7, source:'stippenstructuur' },
      { id:'egg', name:'Eierdoosbeeld', min:0, max:20, sample:7, source:'SupportMaterialPreview' },
      { id:'five-frame', name:'Vijfveld', min:0, max:5, sample:4, source:'tienraamstructuur' },
      { id:'ten-frame', name:'Tienveld', min:0, max:20, sample:7, source:'SupportMaterialPreview' },
      { id:'rekenrek', name:'Rekenrek', min:0, max:20, sample:8, source:'SupportMaterialPreview' },
      { id:'beads', name:'Kralenketting', min:0, max:30, sample:12, source:'SupportMaterialPreview' },
      { id:'tally', name:'Turfstreepjes', min:0, max:30, sample:8, source:'vijfstructuur' },
      { id:'dots', name:'Stippenbeeld', min:0, max:20, sample:7, source:'SupportMaterialPreview' },
      { id:'objects', name:'Telbare voorwerpen', min:0, max:20, sample:7, source:'SupportMaterialPreview' },
      { id:'counters', name:'Rekenfiches', min:0, max:20, sample:8, source:'SupportMaterialPreview' },
      { id:'mab', name:'MAB-materiaal', min:0, max:9999, sample:123, source:'MAB.tsx en SupportMaterialPreview' },
      { id:'place-value', name:'Plaatswaardetabel', min:0, max:9999, sample:123, source:'SupportMaterialPreview' },
      { id:'number-line', name:'Getallenlijn', min:0, max:100, sample:7, source:'SupportMaterialPreview' },
      { id:'hundred', name:'Honderdveld', min:0, max:100, sample:24, source:'SupportMaterialPreview' },
      { id:'split', name:'Splitsbeeld', min:0, max:20, sample:7, source:'number-bond' },
      { id:'money', name:'Geldbeeld', min:0, max:1000, sample:8, source:'officiële ECB-kleuren en euromunten' }
    ];
    const WORDS=['nul','één','twee','drie','vier','vijf','zes','zeven','acht','negen','tien','elf','twaalf','dertien','veertien','vijftien','zestien','zeventien','achttien','negentien','twintig'];
    const COLORS={navy:'#033663',teal:'#28b9aa',red:'#fe5953',white:'#ffffff',purple:'#9b81b8',orange:'#fea020',green:'#54955c',yellow:'#fee020',line:'#8297a5',light:'#edf3f5',skin:'#efbd95'};
    const HAND_SPRITE = "data:image/webp;base64,";
    function esc(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
    function svg(width,height,content,label='Getalbeeld'){return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+width+' '+height+'" width="'+width+'" height="'+height+'" role="img" aria-label="'+esc(label)+'">'+content+'</svg>'}
    function circle(x,y,r,fill,stroke='none',strokeWidth=0){return '<circle cx="'+x+'" cy="'+y+'" r="'+r+'" fill="'+fill+'" stroke="'+stroke+'" stroke-width="'+strokeWidth+'"/>'}
    function rect(x,y,w,h,fill,stroke='none',rx=0,strokeWidth=1){return '<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="'+rx+'" fill="'+fill+'" stroke="'+stroke+'" stroke-width="'+strokeWidth+'"/>'}
    function line(x1,y1,x2,y2,color=COLORS.navy,width=2){return '<line x1="'+x1+'" y1="'+y1+'" x2="'+x2+'" y2="'+y2+'" stroke="'+color+'" stroke-width="'+width+'" stroke-linecap="round"/>'}
    function label(x,y,text,size=14,color=COLORS.navy,anchor='middle'){return '<text x="'+x+'" y="'+y+'" font-family="Trebuchet MS, Arial, sans-serif" font-weight="700" font-size="'+size+'" text-anchor="'+anchor+'" fill="'+color+'">'+esc(text)+'</text>'}
    function dicePips(value,x,y,size){
      const patterns={0:[],1:[[1,1]],2:[[0,0],[2,2]],3:[[0,0],[1,1],[2,2]],4:[[0,0],[2,0],[0,2],[2,2]],5:[[0,0],[2,0],[1,1],[0,2],[2,2]],6:[[0,0],[2,0],[0,1],[2,1],[0,2],[2,2]]};
      const step=size/3.35,start=size*.205;
      return (patterns[value]||[]).map(([col,row])=>circle(x+start+col*step,y+start+row*step,size*.071,COLORS.navy)).join('');
    }

    function renderDice(value){const values=value<=6?[value]:[Math.min(6,value-1),value-Math.min(6,value-1)];return svg(values.length*80,74,values.map((part,index)=>rect(index*80+2,3,67,67,'#fff','#c9d8e0',10,1.7)+dicePips(part,index*80+2,3,67)).join(''),value+' op dobbelstenen')}
    function renderDomino(value){const left=Math.min(6,Math.ceil(value/2)),right=value-left;return svg(142,73,rect(2,3,136,66,'#fff','#c6d6df',8,1.7)+line(70,7,70,65,'#91a4af',1.7)+dicePips(left,3,4,63)+dicePips(right,71,4,63),left+' en '+right+' op domino')}
    function renderFrames(value,five=false){const capacity=five?5:10,frames=Math.max(1,Math.ceil(value/capacity)),cell=28,cols=5,rows=five?1:2,frameWidth=cols*cell+8,frameHeight=rows*cell+8;let result='';for(let frame=0;frame<frames;frame++){const ox=frame*(frameWidth+11);for(let i=0;i<capacity;i++){const x=ox+4+(i%cols)*cell,y=4+Math.floor(i/cols)*cell;result+=rect(x,y,cell,cell,'#fff','#9eb2bd',0,1.3);if(frame*capacity+i<value)result+=circle(x+cell/2,y+cell/2,9,i%10<5?COLORS.teal:COLORS.purple)}}return svg(frames*frameWidth+(frames-1)*11,frameHeight,result,value+' in '+(five?'vijfveld':'tienveld'))}
    function renderEgg(value){const cartons=Math.max(1,Math.ceil(value/10)),width=158,height=81;let result='';for(let carton=0;carton<cartons;carton++){const ox=carton*(width+10);result+=rect(ox+2,3,width-4,height-6,'#dfd1bb','#b8a88f',12,1.3);for(let i=0;i<10;i++){const x=ox+18+(i%5)*29,y=23+Math.floor(i/5)*35;result+='<ellipse cx="'+x+'" cy="'+y+'" rx="12" ry="11" fill="#c2af94"/>';if(carton*10+i<value)result+='<ellipse cx="'+x+'" cy="'+(y-2)+'" rx="8.3" ry="12" fill="#fffaf2" stroke="#d5cbbd" stroke-width=".8"/>'}}return svg(cartons*width+(cartons-1)*10,height,result,value+' eieren')}
    function renderRekenrek(value){const width=222,height=84;let result=rect(2,2,width-4,height-4,'#fff','#b7cad3',8,1.5);for(let row=0;row<2;row++){const y=25+row*35;result+=line(13,y,width-13,y,'#9aaab3',2);for(let i=0;i<10;i++){const active=row*10+i<value,x=18+i*18.5;result+=circle(x,y,7,active?(i<5?COLORS.red:COLORS.white):'#edf1f3',active&&i>=5?'#9caeb6':'#d9e2e7',1)}}return svg(width,height,result,value+' kralen op het rekenrek')}
    function renderBeads(value){const total=value<=10?10:value<=20?20:30,rows=Math.ceil(total/10),width=213,height=rows*30+8;let result='';for(let row=0;row<rows;row++){const y=17+row*30;result+=line(5,y,width-5,y,'#9babb5',1.8);for(let col=0;col<10;col++){const position=row*10+col,active=position<value;result+=circle(12+col*20,y,7,active?(Math.floor(position/5)%2===0?COLORS.red:'#fff'):'#eef2f4',active&&Math.floor(position/5)%2===1?'#98aab5':'#d8e0e5',1)}}return svg(width,height,result,value+' kralen')}
    function renderTally(value){const groups=Math.max(1,Math.ceil(value/5));let result='';for(let group=0;group<groups;group++){const amount=Math.min(5,Math.max(0,value-group*5)),ox=group*53;for(let i=0;i<Math.min(amount,4);i++)result+=line(ox+8+i*9,10,ox+8+i*9,51,COLORS.navy,3);if(amount===5)result+=line(ox+3,45,ox+40,15,COLORS.teal,3.3)}return svg(groups*53,60,result,value+' turfstreepjes')}
    function renderDots(value,kind='dots'){const columns=5,rows=Math.max(1,Math.ceil(value/columns)),width=154,height=rows*31+8;let result='';for(let i=0;i<value;i++){const x=13+(i%columns)*29,y=17+Math.floor(i/columns)*31;if(kind==='objects'){const redGroup=Math.floor(i/5)%2===0,apple=redGroup?'#f46c61':'#79b76d',edge=redGroup?'#d84f49':'#568f50';result+='<path d="M'+(x-1)+' '+(y-6)+' C'+(x-9)+' '+(y-11)+' '+(x-13)+' '+(y-2)+' '+(x-10)+' '+(y+6)+' C'+(x-8)+' '+(y+13)+' '+(x-3)+' '+(y+13)+' '+x+' '+(y+11)+' C'+(x+3)+' '+(y+13)+' '+(x+8)+' '+(y+13)+' '+(x+10)+' '+(y+6)+' C'+(x+13)+' '+(y-2)+' '+(x+9)+' '+(y-11)+' '+(x+1)+' '+(y-6)+' Z" fill="'+apple+'" stroke="'+edge+'" stroke-width=".85"/>';result+='<path d="M'+x+' '+(y-5)+' Q'+(x+1)+' '+(y-10)+' '+(x+3)+' '+(y-12)+'" fill="none" stroke="#786044" stroke-width="1.5" stroke-linecap="round"/><path d="M'+(x+2)+' '+(y-10)+' Q'+(x+8)+' '+(y-15)+' '+(x+10)+' '+(y-9)+' Q'+(x+6)+' '+(y-6)+' '+(x+2)+' '+(y-10)+'Z" fill="#78a968"/><path d="M'+(x-7)+' '+(y-1)+' Q'+(x-9)+' '+(y+3)+' '+(x-6)+' '+(y+6)+'" fill="none" stroke="rgba(255,255,255,.66)" stroke-width="1.6" stroke-linecap="round"/>'}else if(kind==='counters'){result+=circle(x,y,10,Math.floor(i/5)%2===0?COLORS.teal:COLORS.purple,'#fff',1)}else result+=circle(x,y,8,Math.floor(i/5)%2===0?COLORS.navy:COLORS.teal)}return svg(width,height,result,value+' '+(kind==='objects'?'voorwerpen':kind==='counters'?'fiches':'stippen'))}
    function renderMab(value){const thousands=Math.floor(value/1000),hundreds=Math.floor(value%1000/100),tens=Math.floor(value%100/10),units=value%10;let x=3,result='';const outline='rgba(3,54,99,.28)',light='rgba(255,255,255,.58)';function grid(ox,oy,w,h,color,step){let part=rect(ox,oy,w,h,color,outline,1,1);for(let n=1;n<10;n++){if(w>step)part+=line(ox+n*step,oy,ox+n*step,oy+h,light,.6);part+=line(ox,oy+n*step,ox+w,oy+n*step,light,.6)}return part}for(let i=0;i<thousands;i++){const front=49,depth=12,top=15;result+='<polygon points="'+x+','+top+' '+(x+depth)+','+(top-depth)+' '+(x+front+depth)+','+(top-depth)+' '+(x+front)+','+top+'" fill="#ef6b63" stroke="'+outline+'" stroke-width="1"/><polygon points="'+(x+front)+','+top+' '+(x+front+depth)+','+(top-depth)+' '+(x+front+depth)+','+(top+front-depth)+' '+(x+front)+','+(top+front)+'" fill="#c94f49" stroke="'+outline+'" stroke-width="1"/>';result+=grid(x,top,front,front,COLORS.orange,front/10);for(let n=1;n<10;n++){const offset=n*front/10;result+=line(x+offset,top,x+offset+depth,top-depth,light,.48);result+=line(x+front,top+offset,x+front+depth,top+offset-depth,'rgba(255,255,255,.45)',.48)}x+=front+depth+7}for(let i=0;i<hundreds;i++){result+=grid(x,20,44,44,'#84bd5f',4.4);x+=49}for(let i=0;i<tens;i++){result+=grid(x,20,4.4,44,'#4d9fd0',4.4);x+=8}for(let i=0;i<units;i++){const ux=x+Math.floor(i/5)*8,uy=60-(i%5)*8;result+=rect(ux,uy,4.4,4.4,'#f5aa43',outline,.7,1);if(i===units-1)x+=Math.ceil(units/5)*8}return svg(Math.max(70,x+4),70,result,value+' met MAB-materiaal: eenheden, tientallen, honderdtallen en driedimensionale duizendkubussen')}
    function renderPlace(value){const digits=String(value).padStart(value>=1000?4:value>=100?3:2,'0').split(''),titles=digits.length===4?['D','H','T','E']:digits.length===3?['H','T','E']:['T','E'];let result='';for(let i=0;i<digits.length;i++){const x=i*45;result+=rect(x+1,2,42,70,'#fff','#b5c7d0',4,1.2)+line(x+2,30,x+42,30,'#b5c7d0',1)+label(x+22,22,titles[i],15)+label(x+22,56,digits[i],20,i===digits.length-1?COLORS.teal:COLORS.navy)}return svg(digits.length*45,75,result,value+' in plaatswaardetabel')}
    function renderNumberLine(value){const max=value<=10?10:value<=20?20:100,step=max===100?10:max===20?2:1,width=254;let result=line(10,29,244,29,COLORS.navy,1.7);for(let i=0;i<=10;i++){const x=10+i*23.4;result+=line(x,24,x,35,'#7c919f',1.2)+label(x,52,i*step,9)}const position=10+Math.min(value,max)/max*234;result+=circle(position,29,5,COLORS.teal);return svg(width,58,result,value+' op de getallenlijn')}
    function renderHundred(value){const cell=12;let result='';for(let i=0;i<100;i++){const x=2+(i%10)*cell,y=2+Math.floor(i/10)*cell,fill=i<value?(Math.floor(i/10)%2===0?'#d8f2ed':'#ece6f4'):'#fff';result+=rect(x,y,cell,cell,fill,'#afc1ca',0,.7)}return svg(124,124,result,value+' op honderdveld')}
    function renderSplit(value,mode='whole'){
      const first=value>5?5:Math.floor(value/2),second=value-first;
      let result=line(77,36,40,66,'#a4b4bd',2)+line(79,36,114,66,'#a4b4bd',2)+circle(78,23,20,'#fff','#aabcc6',1.5)+circle(39,82,20,'#fff','#aabcc6',1.5)+circle(117,82,20,'#fff','#aabcc6',1.5);
      if(mode!=='none')result+=label(78,29,value,17);
      if(mode==='left'||mode==='solution')result+=label(39,88,first,16);
      if(mode==='right'||mode==='solution')result+=label(117,88,second,16);
      return svg(155,105,result,value+' met lege vakjes voor de splitsing');
    }

    // Educatieve, duidelijk vereenvoudigde illustraties op basis van de officiële ECB-kenmerken.
    const EURO_NOTES={5:{fill:'#e4e6df',ink:'#627067'},10:{fill:'#f5b6a5',ink:'#ab4039'},20:{fill:'#a8cae9',ink:'#285e9e'},50:{fill:'#f3c18c',ink:'#ad6030'},100:{fill:'#b8db9e',ink:'#548441'},200:{fill:'#e5d39c',ink:'#806d37'},500:{fill:'#ccb0db',ink:'#76518c'}};
    function banknoteShape(denomination,x,y=5){
      const palette=EURO_NOTES[denomination],width=92,height=49;
      let result=rect(x,y,width,height,palette.fill,palette.ink,4,1.1);
      result+=rect(x+4,y+4,10,height-8,'rgba(255,255,255,.4)','none',1);
      result+=rect(x+67,y+4,18,height-8,'rgba(255,255,255,.32)','none',2);
      result+='<path d="M'+(x+29)+' '+(y+37)+'v-13q0-12 11-12t11 12v13m-16 0V25q0-6 5-6t5 6v12" fill="none" stroke="'+palette.ink+'" stroke-width="1.8"/>';
      result+=line(x+24,y+38,x+57,y+38,palette.ink,1.1)+label(x+10,y+16,denomination,11,palette.ink)+label(x+77,y+34,denomination,15,palette.ink)+label(x+41,y+47,'EURO',6,palette.ink);
      for(let star=0;star<6;star++){const angle=star*Math.PI/3;result+=circle(x+63+Math.cos(angle)*6,y+16+Math.sin(angle)*6,1,palette.ink)}
      return result;
    }
    function coinShape(cents,x,y=29){
      const euro=cents>=100,value=euro?String(cents/100):String(cents),radius=cents===200?19:cents===100?18:cents===50?17:cents===20?16:cents===10?15:cents===5?14:cents===2?13:12;
      const copper='#c9815d',gold='#d3b45c',silver='#cdd2d1';
      let outer=cents<=5?copper:cents<100?gold:cents===100?gold:silver,inner=cents===100?silver:cents===200?gold:outer;
      let result=circle(x+radius,y,radius,outer,'#8b8376',1.1);
      if(euro)result+=circle(x+radius,y,radius*.69,inner,'rgba(104,98,88,.48)',.8);
      else result+=circle(x+radius,y,radius*.83,'none','rgba(255,255,255,.58)',.75);
      result+='<path d="M'+(x+radius+3)+' '+(y-7)+'l4-2 2 3-2 2 3 2-3 3 1 3-4 2-3-2-2 2-3-3 2-3-2-3 3-2z" fill="rgba(255,255,255,.3)" stroke="rgba(74,73,63,.4)" stroke-width=".6"/>';
      result+=label(x+radius-3,y+4,value,cents>=100?13:11,'#4b463e');
      result+=label(x+radius,y+radius-5,euro?'EURO':'CENT',5,'#5d564c');
      return {markup:result,width:radius*2+7};
    }
    function renderMoney(value,mode='auto'){
      let result='',x=2;
      const denominations=mode==='auto'?[50000,20000,10000,5000,2000,1000,500,200,100,50,20,10,5,2,1]:[Math.round(Number(mode)*100)];
      let remaining=mode==='auto'?Math.round(Number(value)*100):denominations[0];
      for(const denomination of denominations){let iterations=0;while(remaining>=denomination&&iterations<12){if(denomination>=500){result+=banknoteShape(denomination/100,x);x+=99}else{const coin=coinShape(denomination,x);result+=coin.markup;x+=coin.width}remaining-=denomination;iterations++}}
      return svg(Math.max(45,x+2),59,result,(mode==='auto'?value:Number(mode))+' euro');
    }
    function renderFingerSprite(value){
      if(!HAND_SPRITE)return '<div class="missing">Handbeeld '+value+' wordt geladen.</div>';
      function hand(amount,mirrored=false){const column=amount%3,row=Math.floor(amount/3),x=column/2*100,y=row*100;return '<div class="finger-sprite'+(mirrored?' mirrored':'')+'" aria-label="'+amount+' vingers" style="background-position:'+x+'% '+y+'%"></div>'}
      if(value<=5)return '<div class="finger-group" role="img" aria-label="Handbeeld '+value+'">'+hand(value)+'</div>';
      return '<div class="finger-group double" role="img" aria-label="Handbeeld '+value+': vijf en '+(value-5)+'">'+hand(5,true)+hand(value-5,false)+'</div>';
    }
    function renderFingerIcon(){return renderFingerSprite(5)}

    function renderWerkbladstudioGetalbeeld(id,value,settings={}){
      switch(id){
        case'fingers':return renderFingerSprite(value);
        case'dice':return renderDice(value);case'domino':return renderDomino(value);case'egg':return renderEgg(value);case'five-frame':return renderFrames(value,true);case'ten-frame':return renderFrames(value);case'rekenrek':return renderRekenrek(value);case'beads':return renderBeads(value);case'tally':return renderTally(value);case'dots':return renderDots(value);case'objects':return renderDots(value,'objects');case'counters':return renderDots(value,'counters');case'mab':return renderMab(value);case'place-value':return renderPlace(value);case'number-line':return renderNumberLine(value);case'hundred':return renderHundred(value);case'split':return renderSplit(value,settings.splitMode||'whole');case'money':return renderMoney(value,settings.moneyMode||'auto');default:return '<div class="missing">Onbekend getalbeeld.</div>';
      }
    }


function werkbladstudioGetalwoord(value) { return WORDS[value] || String(value); }

// Elke oefening gebruikt dezelfde eerste deelhoeveelheid als het zichtbare beeld.
function werkbladstudioGetalbeeldDelen(material, value) {
  const amount = Number(value);
  if (material === 'dice') {
    const first = amount <= 6 ? amount : Math.min(6, amount - 1);
    return [first, amount - first];
  }
  if (material === 'domino') {
    const first = Math.min(6, Math.ceil(amount / 2));
    return [first, amount - first];
  }
  if (material === 'split') {
    const first = amount > 5 ? 5 : Math.floor(amount / 2);
    return [first, amount - first];
  }
  if (material === 'mab' || material === 'place-value') {
    const place = amount >= 1000 ? 1000 : amount >= 100 ? 100 : amount >= 10 ? 10 : 1;
    const first = Math.floor(amount / place) * place;
    return [first, amount - first];
  }
  if (material === 'money') {
    const first = [500, 200, 100, 50, 20, 10, 5, 2, 1, .5, .2, .1, .05, .02, .01].find((denomination) => denomination <= amount) || 0;
    return [first, Math.round((amount - first) * 100) / 100];
  }
  const first = Math.min(5, amount);
  return [first, Math.max(0, amount - first)];
}

window.GETALBEELDEN_MATERIALS=GETALBEELDEN_MATERIALS;window.HAND_SPRITE=HAND_SPRITE;window.renderWerkbladstudioGetalbeeld=renderWerkbladstudioGetalbeeld;window.werkbladstudioGetalwoord=werkbladstudioGetalwoord;
